WITH product_segment_join AS (SELECT t.transactionid, t.productid, t.customerid, c.segment, t.amount FROM transactions_1k t JOIN customers c ON t.customerid = c.customerid JOIN products p ON t.productid = p.productid) SELECT segment, productid, COUNT(*) as transaction_count, SUM(amount) as total_value FROM product_segment_join GROUP BY segment, productid ORDER BY total_value DESC;
